grant create on schema api,app_private,finance_private to git_tutor_commands;
create table app_private.operation_proposal_supersessions(previous_proposal_id uuid primary key references app_private.operation_proposals(id),replacement_proposal_id uuid not null unique references app_private.operation_proposals(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,created_at timestamptz not null default now(),check(previous_proposal_id<>replacement_proposal_id));
create table finance_private.cancellation_customer_finances(proposal_id uuid not null references app_private.operation_proposals(id),enrollment_id uuid not null references app_private.enrollments(id),charge_id uuid not null references finance_private.charges(id),snapshot jsonb not null,snapshot_hash text not null,primary key(proposal_id,enrollment_id));
create table finance_private.cancellation_compensation_terms(id uuid primary key default gen_random_uuid(),proposal_id uuid not null unique references app_private.operation_proposals(id),occurrence_id uuid not null references app_private.occurrences(id),tutor_id uuid not null references app_private.tutors(id),base_fee_agreement_id uuid references finance_private.tutor_fee_agreements(id),amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),reviewed_by uuid not null references app_private.accounts(id),command_id uuid not null,created_at timestamptz not null default now());
create table finance_private.cancellation_compensation_obligations(id uuid primary key default gen_random_uuid(),proposal_id uuid not null unique references app_private.operation_proposals(id),compensation_terms_id uuid not null references finance_private.cancellation_compensation_terms(id),occurrence_id uuid not null references app_private.occurrences(id),tutor_id uuid not null references app_private.tutors(id),amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),state text not null default 'approved_pending_T08_posting' check(state='approved_pending_T08_posting'),scope text not null default 'occurrence_total_after_cancellation' check(scope='occurrence_total_after_cancellation'),command_id uuid not null,created_at timestamptz not null default now());
do $$declare t text;n text;begin foreach t in array array['operation_proposal_supersessions','cancellation_customer_finances','cancellation_compensation_terms','cancellation_compensation_obligations'] loop n:=case when t='operation_proposal_supersessions' then 'app_private' else 'finance_private' end;execute format('alter table %I.%I enable row level security',n,t);execute format('grant select,insert on %I.%I to git_tutor_commands',n,t);execute format('create policy commands_access on %I.%I to git_tutor_commands using(true) with check(true)',n,t);execute format('revoke all on %I.%I from public,anon,authenticated,service_role,git_tutor_worker',n,t);execute format('create trigger immutable_cancellation before update or delete on %I.%I for each row execute function app_private.reject_immutable_change()',n,t);end loop;end $$;
create function finance_private.finance_cancellation_snapshot(p_enrollment_id uuid,p_remedy text,p_platform boolean) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare e app_private.enrollments%rowtype;o app_private.occurrences%rowtype;q app_private.quotes%rowtype;c finance_private.charges%rowtype;r app_private.package_reservations%rowtype;policy jsonb;balance jsonb;cancel_window jsonb;basis integer;net bigint;retained bigint;release_cash bigint;release_quanta bigint:=0;resolved text:=p_remedy;expires timestamptz;begin
 select * into e from app_private.enrollments where id=p_enrollment_id;select * into o from app_private.occurrences where id=e.occurrence_id;select * into q from app_private.quotes where id=e.current_quote_id;select * into c from finance_private.charges where enrollment_id=e.id;
 if c.id is null or e.state not in('held','confirmed') or o.state not in('forming','confirmed') then raise exception 'CONSENT_REQUIRED';end if;if o.start_at<=now() then raise exception 'WINDOW_CLOSED';end if;
 policy:=app_private.policy_content(q.policy_version_id);balance:=finance_private.finance_charge_balance(c.id);if balance->>'reconciliation_state'<>'clear' then raise exception 'STATE_CONFLICT';end if;
 select * into r from app_private.package_reservations where enrollment_id=e.id and state in('reserved','partially_consumed','consumed') order by created_at desc limit 1;
 if p_platform then basis:=10000;expires:=o.start_at;else
  select value into cancel_window from jsonb_array_elements(policy->'customer_cancellation_windows') where extract(epoch from(o.start_at-now()))/60 >=(value->>'minimum_minutes_before_start')::numeric and(value->>'maximum_minutes_before_start_exclusive' is null or extract(epoch from(o.start_at-now()))/60<(value->>'maximum_minutes_before_start_exclusive')::numeric);
  basis:=(cancel_window->>'refund_basis_points')::int;expires:=o.start_at-make_interval(mins=>(cancel_window->>'minimum_minutes_before_start')::int);
 end if;if basis is null then raise exception 'POLICY_INCOMPLETE';end if;
 if r.id is not null then
  if r.state<>'reserved' or basis<>10000 then raise exception 'POLICY_INCOMPLETE';end if;
  select coalesce(sum((delta->>'reserved_credit_quanta')::numeric),0)::bigint into release_quanta from app_private.entitlement_movements where reservation_id=r.id;
 end if;
 if resolved='policy_default' then resolved:=case when r.id is not null then 'package_entitlement_restoration' else 'monetary_account_credit' end;end if;
 if not(policy->'allowed_refund_remedies'?resolved) or(resolved='package_entitlement_restoration' and r.id is null) then raise exception 'POLICY_INCOMPLETE';end if;
 net:=(balance->>'commercial_net_minor')::bigint;retained:=net-floor(net::numeric*basis/10000)::bigint;release_cash:=greatest(0,(balance->>'allocated_cash_minor')::bigint-retained);
 return jsonb_build_object('enrollment_id',e.id,'charge_id',c.id,'quote_id',q.id,'policy_version_id',q.policy_version_id,'charge_balance',balance,'refund_basis_points',basis,'retained_net_minor',retained,'release_cash_minor',release_cash,'reservation_id',r.id,'reservation_version',r.version,'released_credit_quanta',release_quanta,'remedy',resolved,'window_expires_at',expires,'allocation_ids',coalesce((select jsonb_agg(a.id order by a.id) from finance_private.payment_allocations a where a.charge_id=c.id and a.amount_minor>coalesce((select sum(v.amount_minor) from finance_private.allocation_reversals v where v.allocation_id=a.id),0)),'[]'));
end $$;
create function api.revise_cancellation_proposal(p_proposal_id uuid,p_tutor_compensation_minor bigint,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();context jsonb;old app_private.operation_proposals%rowtype;p app_private.operation_proposals%rowtype;o app_private.occurrences%rowtype;fee finance_private.tutor_fee_agreements%rowtype;ct app_private.operation_customer_terms%rowtype;e app_private.enrollments%rowtype;q app_private.quotes%rowtype;snapshot jsonb;terms jsonb;teacher jsonb;expiry timestamptz;compensation uuid:=gen_random_uuid();snapshots jsonb:='{}';begin
 perform app_private.require_role(actor,'admin');select * into old from app_private.operation_proposals where id=p_proposal_id;
 if old.id is null or old.kind<>'cancellation_remedy' then raise exception 'NOT_FOUND';end if;
 context:=app_private.booking_begin(actor,'revise_cancellation_proposal',jsonb_build_object('proposal_id',p_proposal_id,'tutor_compensation_minor',p_tutor_compensation_minor,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 perform app_private.booking_lock_occurrence_finances(array[old.occurrence_id]);select * into old from app_private.operation_proposals where id=old.id for update;select * into o from app_private.occurrences where id=old.occurrence_id;
 if old.version is distinct from p_expected_version or not coalesce(app_private.booking_proposal_fresh(old.id),false) then raise exception 'VERSION_CONFLICT';end if;
 if length(btrim(p_reason)) not between 1 and 2000 or p_reason is null then raise exception 'VALIDATION_ERROR';end if;
 select * into fee from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id;
 if p_tutor_compensation_minor is null or p_tutor_compensation_minor<0 or p_tutor_compensation_minor>coalesce(fee.fee_minor,0) then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
 if fee.id is not null then perform app_private.require_role(fee.approved_by,'admin');end if;
 if app_private.policy_content(old.policy_version_id)->>'tutor_cancellation_compensation_rule'<>'reviewed_exact_adjustment' then raise exception 'POLICY_INCOMPLETE';end if;
 expiry:=old.expires_at;
 for ct in select * from app_private.operation_customer_terms where proposal_id=old.id order by enrollment_id loop
  snapshot:=finance_private.finance_cancellation_snapshot(ct.enrollment_id,old.requested_terms->>'remedy',old.target_type='occurrence');snapshots:=snapshots||jsonb_build_object(ct.enrollment_id::text,snapshot);expiry:=least(expiry,(snapshot->>'window_expires_at')::timestamptz);
 end loop;
 if expiry<=now() then raise exception 'WINDOW_CLOSED';end if;
 insert into app_private.operation_proposals(kind,target_type,target_id,occurrence_id,base_target_version,base_occurrence_version,base_roster_hash,policy_version_id,requested_terms,expires_at,created_by,reason) values(old.kind,old.target_type,old.target_id,o.id,old.base_target_version,o.version,app_private.booking_roster_fingerprint(o.id),old.policy_version_id,old.requested_terms,expiry,actor,p_reason) returning * into p;
 for ct in select * from app_private.operation_customer_terms where proposal_id=old.id order by enrollment_id loop
  snapshot:=snapshots->ct.enrollment_id::text;select * into e from app_private.enrollments where id=ct.enrollment_id;select * into q from app_private.quotes where id=e.current_quote_id;
  terms:=app_private.booking_proposal_customer_json(e.id,q.policy_version_id,o.start_at,o.end_at,(snapshot->>'retained_net_minor')::bigint,snapshot->>'remedy');
  terms:=terms||jsonb_build_object('remedy_amount_minor',(snapshot->>'release_cash_minor')::bigint,'restored_credit_quanta',0,'released_credit_quanta',(snapshot->>'released_credit_quanta')::bigint);
  insert into app_private.operation_customer_terms(proposal_id,learner_id,enrollment_id,source_quote_id,terms,terms_hash,financial_terms_ready) values(p.id,e.learner_id,e.id,q.id,terms,app_private.booking_proposal_hash(p.id,'learner',e.learner_id,terms,p.expires_at,p.base_target_version),true);
  insert into finance_private.cancellation_customer_finances(proposal_id,enrollment_id,charge_id,snapshot,snapshot_hash) values(p.id,e.id,(snapshot->>'charge_id')::uuid,snapshot,app_private.catalog_hash(snapshot));
 end loop;
 insert into finance_private.cancellation_compensation_terms(id,proposal_id,occurrence_id,tutor_id,base_fee_agreement_id,amount_minor,reviewed_by,command_id) values(compensation,p.id,o.id,o.tutor_id,fee.id,p_tutor_compensation_minor,actor,(context->>'command_id')::uuid);
 teacher:=app_private.booking_proposal_tutor_json(o.id,fee.id,o.start_at,o.end_at,o.target_tier)||jsonb_build_object('fee_agreement_id',null,'fee_minor',p_tutor_compensation_minor,'fee_agreement_state','reviewed_cancellation','cancellation_compensation_id',compensation);
 insert into finance_private.operation_tutor_terms(proposal_id,tutor_id,terms,terms_hash) values(p.id,o.tutor_id,teacher,app_private.booking_proposal_hash(p.id,'tutor',o.tutor_id,teacher,p.expires_at,p.base_target_version));
 update app_private.operation_proposals set state='declined',version=version+1,invalidated_reason='superseded_by_review',updated_at=now() where id=old.id;
 insert into app_private.operation_proposal_supersessions(previous_proposal_id,replacement_proposal_id,actor_account_id,command_id) values(old.id,p.id,actor,(context->>'command_id')::uuid);
 perform app_private.booking_enqueue_due(o.id,p.expires_at);perform set_config('response.status','201',true);
 return app_private.booking_finish(context,p.id,p.version,jsonb_build_object('proposal_id',p.id,'terms_hash',app_private.booking_proposal_admin_hash(p.id),'expires_at',p.expires_at,'required_actions','["review_terms"]'::jsonb,'replaces_proposal_id',old.id),'cancellation_proposal_reviewed',jsonb_build_object('proposal_id',p.id,'replaces_proposal_id',old.id,'occurrence_id',o.id));
end $$;
alter function app_private.booking_proposal_dto(uuid,uuid,text,uuid,boolean) rename to booking_proposal_dto_before_cancellation;
create function app_private.booking_proposal_dto(p_actor uuid,p_id uuid,p_view text,p_learner_id uuid,p_group boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;begin
 result:=app_private.booking_proposal_dto_before_cancellation(p_actor,p_id,p_view,p_learner_id,p_group);
 if p_view='tutor' and result->'terms'->>'fee_agreement_state'='reviewed_cancellation' then result:=result||jsonb_build_object('can_accept',app_private.booking_proposal_fresh(p_id) and result->>'state' in('proposed','accepted') and result->>'accepted_at' is null);end if;
 return result||jsonb_build_object('replaces_proposal_id',(select previous_proposal_id from app_private.operation_proposal_supersessions where replacement_proposal_id=p_id),'superseded_by_proposal_id',(select replacement_proposal_id from app_private.operation_proposal_supersessions where previous_proposal_id=p_id));
end $$;
alter function app_private.booking_proposal_participant(uuid,uuid,text) rename to booking_proposal_participant_before_cancellation;
create function app_private.booking_proposal_participant(p_actor uuid,p_id uuid,p_hash text) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;begin result:=app_private.booking_proposal_participant_before_cancellation(p_actor,p_id,p_hash);
 if result->>'type'='tutor' and exists(select 1 from finance_private.cancellation_compensation_terms where proposal_id=p_id) then result:=result||jsonb_build_object('financial_terms_ready',true);end if;return result;
end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='finance_private' and p.proname='finance_cancellation_snapshot') or(n.nspname='api' and p.proname='revise_cancellation_proposal') or(n.nspname='app_private' and p.proname in('booking_proposal_dto','booking_proposal_dto_before_cancellation','booking_proposal_participant','booking_proposal_participant_before_cancellation')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';

